import sys

MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    values = data[1:]

    factors = []
    for x in values:
        current = {}
        p = 2
        while p * p <= x:
            while x % p == 0:
                current[p] = current.get(p, 0) + 1
                x //= p
            p += 1
        if x > 1:
            current[x] = current.get(x, 0) + 1
        factors.append(current)

    primes = set().union(*(f.keys() for f in factors))
    answer = 1

    for prime in primes:
        steps = [f.get(prime, 0) for f in factors]
        total = sum(steps)
        limit = 2 * total

        powers = [1] * (limit + 1)
        for h in range(1, limit + 1):
            powers[h] = powers[h - 1] * prime % MOD

        # dp_not_zero[h]: paths at height h that have not visited zero.
        # dp_zero[h]: paths at height h that have visited zero.
        dp_not_zero = [0] * (limit + 1)
        dp_zero = [0] * (limit + 1)
        for h in range(total + 1):
            if h == 0:
                dp_zero[h] = 1
            else:
                dp_not_zero[h] = powers[h]

        for step in steps:
            next_not_zero = [0] * (limit + 1)
            next_zero = [0] * (limit + 1)
            for h in range(limit + 1):
                a = dp_not_zero[h]
                b = dp_zero[h]
                if not (a or b):
                    continue

                destinations = (h + step,) if step == 0 else (h + step, h - step)
                for nh in destinations:
                    if nh < 0 or nh > limit:
                        continue
                    weight = powers[nh]
                    if nh == 0:
                        next_zero[nh] = (next_zero[nh] + (a + b) * weight) % MOD
                    else:
                        next_not_zero[nh] = (next_not_zero[nh] + a * weight) % MOD
                        next_zero[nh] = (next_zero[nh] + b * weight) % MOD
            dp_not_zero, dp_zero = next_not_zero, next_zero

        answer = answer * (sum(dp_zero) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    solve()

