from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, i))

        largest = second_largest = 0
        largest_id = -1
        gains = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for left, pair_id in by_right[right]:
                if left > largest:
                    second_largest = largest
                    largest = left
                    largest_id = pair_id
                elif left > second_largest:
                    second_largest = left

            # Valid subarrays ending here start strictly after the largest
            # left endpoint among conflicting pairs already encountered.
            total += right - largest

            # Removing the unique pair attaining largest relaxes the bound
            # by largest - second_largest for this right endpoint.
            if largest_id != -1:
                gains[largest_id] += largest - second_largest

        return total + max(gains)

