from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n+1)]
        for i, (a,b) in enumerate(conflictingPairs):
            if a>b: a,b=b,a
            by_right[b].append((a,i))
        top=second=0
        top_id=-1
        gains=[0]*len(conflictingPairs)
        base=0
        for r in range(1,n+1):
            for v,i in by_right[r]:
                if v>top:
                    second=top
                    top=v
                    top_id=i
                elif v>second:
                    second=v
            base += r-top
            if top_id>=0:
                gains[top_id]+=top-second
        return base+max(gains)

