import sys
import math

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    raw = data[2:]
    processes = [tuple(raw[i:i + 4]) for i in range(0, len(raw), 4)]

    def minimum_cost(a, p, b, q, target):
        period = b // math.gcd(a, b)
        cap = (target + a - 1) // a
        top = (target - 1) // a
        best = cap * p  # Pure S machines suffice.
        for r in range(min(period, top + 1)):
            last = r + ((top - r) // period) * period
            for x in (r, last):
                y = max(0, (target - a * x + b - 1) // b)
                best = min(best, x * p + y * q)
        return best

    def feasible(target):
        total = 0
        for a, p, b, q in processes:
            total += minimum_cost(a, p, b, q, target)
            if total > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while low + 1 < high:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

