class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Binomial coefficients C[a][b] for a <= n.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for a in range(1, n + 1):
            comb[a][0] = comb[a][a] = 1
            for b in range(1, a):
                comb[a][b] = (comb[a - 1][b - 1] + comb[a - 1][b]) % MOD

        def reduction_steps(x: int) -> int:
            steps = 0
            while x != 1:
                x = x.bit_count()
                steps += 1
            return steps

        # A number with t set bits takes one step to become t, then
        # reduction_steps(t) additional steps.
        acceptable = [False] * (n + 1)
        for t in range(1, n + 1):
            acceptable[t] = reduction_steps(t) <= k - 1

        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                # Match this prefix to s up to i-1, then choose 0 here.
                for total_ones in range(1, n + 1):
                    needed = total_ones - prefix_ones
                    if 0 <= needed <= remaining and acceptable[total_ones]:
                        answer += comb[remaining][needed]
                prefix_ones += 1

        return answer % MOD

