        C[0][0] = 1
        for a in range(1, n + 1):
            C[a][0] = C[a][a] = 1
            for b in range(1, a):
                C[a][b] = (C[a - 1][b - 1] + C[a - 1][b]) % MOD

        def steps(x):
            count = 0
            while x != 1:
                x = x.bit_count()
                count += 1
            return count

        reducible = [False] * (n + 1)
        for ones in range(1, n + 1):
            reducible[ones] = steps(ones) <= k - 1

