import sys, heapq

def solve():
    data=list(map(int,sys.stdin.buffer.read().split()))
    it=iter(data)
    H=next(it); W=next(it); X=next(it)
    P=next(it)-1; Q=next(it)-1
    a=[ [next(it) for _ in range(W)] for _ in range(H)]
    seen=bytearray(H*W)
    start=P*W+Q
    seen[start]=1
    strength=a[P][Q]
    heap=[]
    def add(r,c):
        k=r*W+c
        if not seen[k]:
            seen[k]=1
            heapq.heappush(heap,(a[r][c],k))
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        r=P+dr;c=Q+dc
        if 0<=r<H and 0<=c<W: add(r,c)
    while heap:
        s,k=heap[0]
        if s*X>=strength: break
        heapq.heappop(heap)
        strength+=s
        r,c=divmod(k,W)
        if r>0:add(r-1,c)
        if r+1<H:add(r+1,c)
        if c>0:add(r,c-1)
        if c+1<W:add(r,c+1)
    print(strength)
