import sys

def mountain(x):
    # Mountain iff the odd part of x is 1 modulo 4.
    while x % 2 == 0:
        x //= 2
    return x % 4 == 1

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:1+n]
    limit = (1 << 100) - a[-1] - 1
    # Evaluate promising starts near each input offset and on an initial range.
    # The fold pattern is generated directly from its defining bit rule.
    candidates = set(range(1, min(limit, 200000) + 1))
    for x in a:
        for d in range(-2000, 2001):
            i = x + d
            if 1 <= i <= limit:
                candidates.add(i)
    ans = 0
    for i in candidates:
        score = sum(mountain(i + x) for x in a)
        if score > ans:
            ans = score
    print(ans)

if __name__ == '__main__':
    main()

