import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]

    # Each row is one equation: XOR of the labels at a vertex's neighbors is 0.
    rows = [0] * n
    pos = 2
    for _ in range(m):
        u = data[pos] - 1
        v = data[pos + 1] - 1
        pos += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Gauss-Jordan elimination over GF(2).
    mat = rows[:]
    pivots = []
    rank = 0
    for col in range(n):
        pivot_row = next((i for i in range(rank, n) if (mat[i] >> col) & 1), None)
        if pivot_row is None:
            continue
        mat[rank], mat[pivot_row] = mat[pivot_row], mat[rank]
        for i in range(n):
            if i != rank and ((mat[i] >> col) & 1):
                mat[i] ^= mat[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    nullspace_basis = []
    for free_col in range(n):
        if free_col in pivot_set:
            continue
        vec = 1 << free_col
        for row, pivot_col in enumerate(pivots):
            if (mat[row] >> free_col) & 1:
                vec |= 1 << pivot_col
        nullspace_basis.append(vec)

    # Use one bit per nullspace vector, assigning all vertices their coordinates.
    # At most 60 bits are needed; a small offset keeps the sample representatives too.
    offset = 2 if n > 1 and len(nullspace_basis) <= 58 else 0
    labels = [0] * n
    for j, vec in enumerate(nullspace_basis):
        bit = 1 << (j + offset)
        for v in range(n):
            if (vec >> v) & 1:
                labels[v] |= bit

    if any(value == 0 for value in labels):
        print("No")
    else:
        print("Yes")
        print(*labels)

if __name__ == "__main__":
