def solve(n, edges):
    rows=[0]*n
    for u,v in edges:
        rows[u] |= 1<<v; rows[v] |= 1<<u
    mat=rows[:]; pivots=[]; r=0
    for c in range(n):
        p=next((i for i in range(r,n) if mat[i]>>c&1),None)
        if p is None: continue
        mat[r],mat[p]=mat[p],mat[r]
        for i in range(n):
            if i!=r and mat[i]>>c&1: mat[i]^=mat[r]
        pivots.append(c); r+=1
