            x=1<<f
            for i,c in enumerate(pivots):
                if mat[i]>>f&1: x|=1<<c
            basis.append(x)
    labels=[0]*n
    for j,x in enumerate(basis):
        for v in range(n):
            if x>>v&1: labels[v]|=1<<j
    return labels if all(labels) else None

