import math
class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = (n + 1) // 2
        evens = n // 2
        def ways(o, e, need):
            if o + e == 0:
                return 1
            if need == 1:
                ok = (o == e or o == e + 1)
            else:
                ok = (e == o or e == o + 1)
            return math.factorial(o) * math.factorial(e) if ok else 0
        available = list(range(1, n + 1))
        result = []
        previous = 0
        while available:
            chosen = None
            for x in available:
                if previous and (x & 1) == previous:
                    continue
                o = odds - (1 if x & 1 else 0)
                e = evens - (0 if x & 1 else 1)
                # next parity is opposite of x
                cnt = ways(o, e, 0 if x & 1 else 1)
                if k > cnt:
                    k -= cnt
                else:
                    chosen = x
                    odds, evens = o, e
                    previous = x & 1
                    available.remove(x)
                    result.append(x)
                    break
            if chosen is None:
                return []
        return result

