class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        # Powers of ten modulo k for each decimal position.
        powers = [1] * n
        for i in range(1, n):
            powers[i] = (powers[i - 1] * 10) % k

        # Each half digit contributes to its own position and its mirror.
        coeff = []
        for j in range(m):
            mirror = n - 1 - j
            if mirror == j:
                coeff.append(powers[j])
            else:
                coeff.append((powers[j] + powers[mirror]) % k)

        # dp[i][r] means the digits from i onward can contribute residue r.
        dp = [None] * (m + 1)
        dp[m] = bytearray([1] + [0] * (k - 1))
        for i in range(m - 1, -1, -1):
            row = bytearray(k)
            c = coeff[i]
            nxt = dp[i + 1]
            for residue in range(k):
                if nxt[residue]:
                    for digit in range(10):
                        row[(residue + c * digit) % k] = 1
            dp[i] = row

        # Greedily select each half digit, retaining a feasible suffix.
        half_digits = []
        residue = 0
        for i, c in enumerate(coeff):
            lowest = 1 if i == 0 else 0
            for digit in range(9, lowest - 1, -1):
                needed = (-residue - c * digit) % k
                if dp[i + 1][needed]:
                    half_digits.append(str(digit))
                    residue = (residue + c * digit) % k
                    break

        half = ''.join(half_digits)
        if n % 2:
            return half + half[:-1][::-1]
        return half + half[::-1]

