from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # next_greater[i] is the first index to the right with a strictly
        # greater value. These are the breakpoints of the prefix maxima
        # when a subarray starts at i.
        next_greater = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            if stack:
                next_greater[i] = stack[-1]
            stack.append(i)

        levels = n.bit_length()
        jump = [next_greater]
        # Aggregate incremented prefix-max values across each jump.
        aggregate = [[nums[i] * (next_greater[i] - i) for i in range(n)]]
        for _ in range(1, levels):
            prev_jump = jump[-1]
            prev_aggregate = aggregate[-1]
            curr_jump = [n] * n
            curr_aggregate = [0] * n
            for i in range(n):
                mid = prev_jump[i]
                if mid < n:
                    curr_jump[i] = prev_jump[mid]
                    curr_aggregate[i] = prev_aggregate[i] + prev_aggregate[mid]
                else:
                    curr_aggregate[i] = prev_aggregate[i]
            jump.append(curr_jump)
            aggregate.append(curr_aggregate)

        prefix_sum = [0] * (n + 1)
        for i, value in enumerate(nums):
            prefix_sum[i + 1] = prefix_sum[i] + value

        def required_operations(left: int, right: int) -> int:
            # Sum the prefix maxima by jumping over complete constant runs.
            pos = left
            raised_sum = 0
            for level in range(levels - 1, -1, -1):
                destination = jump[level][pos]
                if destination <= right:
                    raised_sum += aggregate[level][pos]
                    pos = destination
            raised_sum += nums[pos] * (right - pos + 1)
            return raised_sum - (prefix_sum[right + 1] - prefix_sum[left])

        answer = 0
        for right in range(n):
            # For a fixed right endpoint, operation cost cannot decrease as
            # the left endpoint moves left, so valid starts form a suffix.
            low, high = 0, right
            while low < high:
                mid = (low + high) // 2
                if required_operations(mid, right) <= k:
                    high = mid
                else:
                    low = mid + 1
            answer += right - low + 1

        return answer

