import sys
from collections import Counter

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, k = data[0], data[1]

    counts = Counter()
    for i in range(n):
        a, b = data[2 + 2 * i], data[3 + 2 * i]
        counts[(a, b)] += 1

    # For a fixed selected multiset, functions are optimally ordered by
    # increasing (A-1)/B. Ties commute.
    groups = {}
    for (a, b), count in counts.items():
        groups.setdefault((a - 1) / b, []).append((a, b, min(count, k)))

    # A state maps (number selected, product of slopes) to the greatest
    # accumulated intercept contribution.
    dp = {(0, 1): 0}

    for key in sorted(groups):
        for a, b, count in groups[key]:
            # Identical functions can be selected consecutively.
            powers = [1]
            for _ in range(count):
                powers.append(powers[-1] * a)

            updated = dict(dp)
            for (used, product), value in dp.items():
                for c in range(1, min(count, k - used) + 1):
                    new_product = product * powers[c]
                    if a == 1:
                        added = b * c * product
                    else:
                        added = b * product * (powers[c] - 1) // (a - 1)
                    state = (used + c, new_product)
                    candidate = value + added
                    if candidate > updated.get(state, -1):
                        updated[state] = candidate
            dp = updated

    best = max(value + product for (used, product), value in dp.items() if used == k)
    print(best)

if __name__ == "__main__":
    main()

class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter

        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - ord('a')] += 1

        n = len(s)
        answer = n

        # Try each possible positive frequency in the final string.
        for target in range(1, max(counts) + 1):
            # dp[incoming] is the minimum cost after processing the
            # preceding letter, with `incoming` characters incremented
            # into the current letter.
            dp = [0] + [n + 1] * n

            for count in counts:
                new = [n + 1] * (n + 1)

                for incoming, cost in enumerate(dp):
                    if cost > n:
                        continue
                    available = count + incoming

                    # Leave this letter absent, or make its frequency target.
                    for desired in (0, target):
                        if available >= desired:
                            surplus = available - desired
                            # Surplus characters may be deleted or incremented
                            # to the next letter. Incrementing costs one each.
                            base = cost + surplus
                            for outgoing in range(surplus + 1):
                                value = base
                                if value < new[outgoing]:
                                    new[outgoing] = value
                        else:
                            value = cost + desired - available
                            if value < new[0]:
                                new[0] = value

                dp = new

            answer = min(answer, min(dp))

        return answer

