import sys
from functools import lru_cache

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m, l = data[:3]
    a = data[3:3 + n]
    b = data[3 + n:3 + n + m]
    c = data[3 + n + m:]
    values = a + b + c
    k = len(values)
    full = (1 << k) - 1
    initial_t = (1 << n) - 1
    initial_a = ((1 << m) - 1) << n

    @lru_cache(None)
    def winning(takahashi, aoki, turn):
        hand = takahashi if turn == 0 else aoki
        if hand == 0:
            return False

        table = full ^ (takahashi | aoki)
        cards = hand
        while cards:
            bit = cards & -cards
            cards -= bit
            played = bit.bit_length() - 1
            remaining_hand = hand ^ bit

            # Play the card without taking one from the table.
            if turn == 0:
                if not winning(remaining_hand, aoki, 1):
                    return True
            else:
                if not winning(takahashi, remaining_hand, 0):
                    return True

            # Or take any strictly lower-valued card already on the table.
            candidates = table
            while candidates:
                take_bit = candidates & -candidates
                candidates -= take_bit
                taken = take_bit.bit_length() - 1
                if values[taken] < values[played]:
                    new_hand = remaining_hand | take_bit
                    if turn == 0:
                        if not winning(new_hand, aoki, 1):
                            return True
                    else:
                        if not winning(takahashi, new_hand, 0):
                            return True
        return False

    print('Takahashi' if winning(initial_t, initial_a, 0) else 'Aoki')

