from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        first = p.index('*')
        second = p.index('*', first + 1)
        parts = (p[:first], p[first + 1:second], p[second + 1:])
        n = len(s)

        def occurrences(pattern):
            m = len(pattern)
            if m == 0:
                return list(range(n + 1))
            prefix = [0] * m
            k = 0
            for i in range(1, m):
                while k and pattern[k] != pattern[i]:
                    k = prefix[k - 1]
                if pattern[k] == pattern[i]:
                    k += 1
                prefix[i] = k
            result = []
            k = 0
            for i, ch in enumerate(s):
                while k and pattern[k] != ch:
                    k = prefix[k - 1]
                if pattern[k] == ch:
                    k += 1
                if k == m:
                    result.append(i - m + 1)
                    k = prefix[k - 1]
            return result

        oa, ob, oc = [occurrences(t) for t in parts]
        la, lb, lc = map(len, parts)
        best = n + 1
        for a in oa:
            ib = bisect_left(ob, a + la)
            if ib == len(ob):
                continue
            b = ob[ib]
            ic = bisect_left(oc, b + lb)
            if ic == len(oc):
                continue
            best = min(best, oc[ic] + lc - a)
        return best if best <= n else -1

