class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        i = p.index('*')
        j = p.index('*', i + 1)
        parts = (p[:i], p[i+1:j], p[j+1:])
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))
            out = []
            pos = 0
            while True:
                k = s.find(t, pos)
                if k < 0:
                    break
                out.append(k)
                pos = k + 1
            return out

        occ = [occurrences(t) for t in parts]
        la, lb, lc = map(len, parts)
        best = n + 1
        for a in occ[0]:
            bi = bisect_left(occ[1], a + la)
            if bi == len(occ[1]):
                continue
            b = occ[1][bi]
            ci = bisect_left(occ[2], b + lb)
            if ci == len(occ[2]):
                continue
            c = occ[2][ci]
            best = min(best, c + lc - a)
        return best if best <= n else -1

