from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Iterative postorder traversal, preserving increasing child order.
        order = []
        stack = [(0, False)]
        while stack:
            v, done = stack.pop()
            if done:
                order.append(v)
            else:
                stack.append((v, True))
                for c in reversed(children[v]):
                    stack.append((c, False))

        seq = ''.join(s[v] for v in order)
        pos = [0] * n
        size = [1] * n
        for i, v in enumerate(order):
            pos[v] = i
            if parent[v] != -1:
                size[parent[v]] += size[v]

        # Manacher radii: odd d1[i], even d2[i] centered between i-1 and i.
        d1 = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(d1[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and seq[i - k] == seq[i + k]:
                k += 1
            d1[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        d2 = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(d2[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and seq[i - k - 1] == seq[i + k]:
                k += 1
            d2[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for v in range(n):
            r = pos[v]
            l = r - size[v] + 1
            length = size[v]
            if length & 1:
                answer[v] = d1[(l + r) // 2] >= length // 2 + 1
            else:
                answer[v] = d2[(l + r + 1) // 2] >= length // 2
        return answer

