class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        length = len(str(n))
        lo = 0 if length == 1 else 10 ** (length - 1)
        hi = 10 ** length - 1

        # Sieve primes in the range of possible values.
        is_prime = bytearray(b'\x01') * (hi + 1)
        is_prime[0] = 0
        if hi >= 1:
            is_prime[1] = 0
        for p in range(2, int(hi ** 0.5) + 1):
            if is_prime[p]:
                is_prime[p * p:hi + 1:p] = b'\x00' * (((hi - p * p) // p) + 1)

        if is_prime[n] or is_prime[m]:
            return -1

        # A path's cost includes its initial value and every value reached.
        inf = 10 ** 30
        dist = [inf] * (hi + 1)
        dist[n] = n
        pq = [(n, n)]
        powers = [10 ** i for i in range(length)]

        while pq:
            cost, x = heapq.heappop(pq)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            digits = str(x).zfill(length)
            for i, ch in enumerate(digits):
                digit = ord(ch) - 48
                place = powers[length - 1 - i]
                for new_digit in (digit - 1, digit + 1):
                    if not 0 <= new_digit <= 9:
                        continue
                    # Keep the number's digit count unchanged.
                    if length > 1 and i == 0 and new_digit == 0:
                        continue
                    y = x + (new_digit - digit) * place
                    if not is_prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(pq, (cost + y, y))

        return -1

