import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    k = int(data[0])
    s = data[1].decode()
    t = data[2].decode()

    n, m = len(s), len(t)
    if s == t:
        print('Yes')
    elif abs(n - m) > k:
        print('No')
    elif n == m:
        mismatches = 0
        for a, b in zip(s, t):
            if a != b:
                mismatches += 1
                if mismatches > k:
                    break
        print('Yes' if mismatches <= k else 'No')
    else:
        shorter, longer = (s, t) if n < m else (t, s)
        i = j = skipped = 0
        while i < len(shorter) and j < len(longer):
            if shorter[i] == longer[j]:
                i += 1
                j += 1
            else:
                skipped += 1
                j += 1
                if skipped > k:
                    break
        print('Yes' if skipped <= k else 'No')

if __name__ == '__main__':
    main()

