import heapq

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Reverse each edge so that a traversal from 0 follows paths toward 0
        # in the original graph.
        reverse_graph = [[] for _ in range(n)]
        for a, b, weight in edges:
            reverse_graph[b].append((a, weight))

        inf = float('inf')
        best = [inf] * n
        best[0] = 0
        heap = [(0, 0)]

        # Minimax Dijkstra: best[u] is the smallest possible maximum edge
        # weight on any path from u to node 0.
        while heap:
            cost, node = heapq.heappop(heap)
            if cost != best[node]:
                continue
            for prev, weight in reverse_graph[node]:
                candidate = max(cost, weight)
                if candidate < best[prev]:
                    best[prev] = candidate
                    heapq.heappush(heap, (candidate, prev))

        if any(value == inf for value in best):
            return -1
        return max(best)

