def fast(s):
    stacks=[[] for _ in range(26)]; ans=0
    for i,ch in enumerate(s):
        x=ord(ch)-97; y=25-x
        if stacks[y]: ans += i-stacks[y].pop()
        else: stacks[x].append(i)
    return ans

def ref(s):
    marked=[False]*len(s); ans=0
    for i,c in enumerate(s):
        if marked[i]: continue
        m=chr(122-(ord(c)-97))
        for j in range(i-1,-1,-1):
            if not marked[j] and s[j]==m:
                marked[i]=marked[j]=True; ans+=i-j; break
    return ans
